def vintage_rows(rows,cutoff):
    # Synthetic schema:(permanent_asset_id,observation_time,available_time,revision,value_cents).
    if type(cutoff) is not int or cutoff<0 or type(rows) is not list or len(rows)>128:
        raise ValueError("invalid snapshot boundary")
    seen=set();groups={}
    for row in rows:
        if type(row) is not tuple or len(row)!=5:raise ValueError("invalid revision row")
        asset,obs,available,revision,value=row
        if type(asset) is not str or not asset or any(type(x) is not int for x in row[1:]):
            raise ValueError("invalid revision types")
        if not 0<=obs<=available or revision<0 or value<=0:
            raise ValueError("invalid revision domain")
        key=(asset,obs,revision)
        if key in seen:raise ValueError("duplicate revision key")
        seen.add(key);groups.setdefault((asset,obs),[]).append(row)
    for group in groups.values():
        ordered=sorted(group,key=lambda row:row[3])
        if any(a[2]>b[2] for a,b in zip(ordered,ordered[1:])):
            raise ValueError("revision availability runs backward")
    chosen={}
    for row in rows:
        asset,obs,available,revision,value=row
        if available>cutoff:continue
        key=(asset,obs)
        if key not in chosen or (available,revision)>(chosen[key][2],chosen[key][3]):chosen[key]=row
    return tuple(chosen[key] for key in sorted(chosen))

def bar_backtest(bars,targets,initial_cash,half_spread=0,adverse_slip=0,fee_per_unit=0):
    # OWN schema:(time,opening_reference_cents,closing_mark_cents,open_executable_capacity).
    if type(bars) is not list or type(targets) is not list or len(bars)!=len(targets) or len(bars)>128:
        raise ValueError("invalid bar or target lists")
    if type(initial_cash) is not int or not 0<=initial_cash<=10**9:
        raise ValueError("invalid initial cash")
    if any(type(x) is not int or not 0<=x<=1000 for x in (half_spread,adverse_slip,fee_per_unit)):
        raise ValueError("invalid cost parameters")
    for index,(bar,target) in enumerate(zip(bars,targets)):
        if type(bar) is not tuple or len(bar)!=4 or any(type(x) is not int for x in bar):
            raise ValueError("invalid bar schema")
        time,opening,close,capacity=bar
        if time!=index or not 1<=opening<=10**6 or not 1<=close<=10**6 or not 0<=capacity<=10:
            raise ValueError("invalid bar domain or order")
        if opening<=half_spread+adverse_slip+fee_per_unit:
            raise ValueError("costs exceed supported sell proceeds")
        if type(target) is not int or not 0<=target<=10:raise ValueError("invalid close target")
    cash=initial_cash;position=0;pending=None;rows=[]
    for (time,opening,close,capacity),target in zip(bars,targets):
        delta=0 if pending is None else pending-position
        price=None;executed=0;unfilled=abs(delta)
        if delta>0:
            candidate=opening+half_spread+adverse_slip
            quantity=min(delta,capacity,cash//(candidate+fee_per_unit))
            if quantity:
                cash-=quantity*(candidate+fee_per_unit);position+=quantity
                executed=quantity;price=candidate
        elif delta<0:
            candidate=opening-half_spread-adverse_slip
            quantity=min(-delta,capacity,position)
            if quantity:
                cash+=quantity*(candidate-fee_per_unit);position-=quantity
                executed=-quantity;price=candidate
        unfilled-=abs(executed)
        # Opening attempt expires;mark then accept a NEW close-time target.
        equity=cash+position*close;pending=target
        rows.append((time,executed,price,cash,position,close,equity,target,unfilled))
    return tuple(rows),pending

import hashlib,json,platform

def audited_backtest(history,opens,threshold=0,initial=1000,costs=(1,1,1)):
    # Own one-asset chronological close signal;no fit/search/held-out inference performed.
    vintage_rows(history,0) # validate FULL revision input even if later excluded
    if any(row[0]!="A" for row in history):raise ValueError("only permanent asset A supported")
    if type(opens) is not list or not 1<=len(opens)<=128 or type(costs) is not tuple or len(costs)!=3:
        raise ValueError("invalid audit input schema")
    if type(threshold) is not int or not 0<=threshold<=1000:raise ValueError("invalid rise threshold cents")
    placeholder=[]
    for row in opens:
        if type(row) is not tuple or len(row)!=3:raise ValueError("invalid opening schema")
        time,price,capacity=row;placeholder.append((time,price,price,capacity))
    bar_backtest(placeholder,[0]*len(opens),initial,*costs) # full open/cost domain checks
    bars=[];targets=[];decisions=[]
    for time,opening,capacity in opens:
        snapshot={row[1]:row for row in vintage_rows(history,time)}
        if time not in snapshot or time>0 and time-1 not in snapshot:
            raise ValueError("required point-in-time close unavailable")
        current=snapshot[time]
        previous=None if time==0 else snapshot[time-1]
        target=int(previous is not None and current[4]-previous[4]>threshold)
        bars.append((time,opening,current[4],capacity));targets.append(target)
        decisions.append((time,current,previous,target))
    ledger,pending=bar_backtest(bars,targets,initial,*costs)
    manifest={"kernel":"point-in-time-next-open-v1","python":platform.python_version(),"asset":"A","currency":"OWN-CENTS","history":[list(row) for row in history],"opens":[list(row) for row in opens],"threshold":threshold,"initial_cash":initial,"costs":list(costs)}
    raw=json.dumps(manifest,sort_keys=True,separators=(",",":"),ensure_ascii=True,allow_nan=False)
    return {"schema":1,"run_id":hashlib.sha256(raw.encode("utf-8")).hexdigest(),"manifest":raw,"decisions":tuple(decisions),"ledger":ledger,"pending_target":pending,"final_marked_equity":ledger[-1][6]}

