def local_simulation(verified_principal,grants,request):
    # Own trusted caller/policy boundary,not real authentication.
    if type(verified_principal) is not str or verified_principal not in ("student-a","student-b"):
        raise PermissionError("simulation denied")
    if type(grants) is not frozenset or len(grants)>2 or any(type(p) is not str or p not in ("student-a","student-b") for p in grants) or verified_principal not in grants:
        raise PermissionError("simulation denied")
    required={"schema","history","opens","threshold","initial_cash","costs"}
    if type(request) is not dict or set(request)!=required or type(request["schema"]) is not int or request["schema"]!=1:
        raise ValueError("invalid simulation request")
    result=audited_backtest(request["history"],request["opens"],request["threshold"],request["initial_cash"],request["costs"])
    equity=(request["initial_cash"],)+tuple(row[6] for row in result["ledger"])
    peak=equity[0];max_drop=0
    for value in equity:
        peak=max(peak,value);max_drop=max(max_drop,peak-value)
    # Absolute marked-equity drawdown in synthetic cents,not percentage/future risk.
    summary={"schema":1,"model":"point-in-time-next-open-v1","currency":"OWN-CENTS","run_id":result["run_id"],"final_marked_equity":result["final_marked_equity"],"max_marked_drop_cents":max_drop,"gross_traded_units":sum(abs(row[1]) for row in result["ledger"]),"terminal_position":result["ledger"][-1][4],"pending_target":result["pending_target"]}
    return summary,result

request={"schema":1,"history":[("A",i,i,0,value) for i,value in enumerate([100,110,105,108])],"opens":[(0,100,10),(1,101,10),(2,112,10),(3,104,10)],"threshold":0,"initial_cash":1000,"costs":(1,1,1)}
summary,audit=local_simulation("student-a",frozenset({"student-a"}),request)
print(summary["final_marked_equity"],summary["max_marked_drop_cents"],summary["gross_traded_units"])
print(summary["terminal_position"],summary["pending_target"],summary["currency"])
print("replay",local_simulation("student-a",frozenset({"student-a"}),request)==(summary,audit))
